patch:
diff --git a/repro/cross-drive-ignore.js b/repro/cross-drive-ignore.js
new file mode 100644
index 0000000..922b5df
--- /dev/null
+++ b/repro/cross-drive-ignore.js
@@ -0,0 +1,60 @@
+"use strict";
+
+/*
+ * Repro for "files on a different drive are not ignored on Windows".
+ * Runs on any OS: Node's `path` is swapped for `path.win32` and cwd is faked
+ * as C:\Project, so ESLint and @eslint/config-array use Windows path logic.
+ */
+const Module = require("node:module");
+const nodePath = require("node:path");
+
+const CWD = "C:\\Project";
+const originalLoad = Module._load;
+
+Module._load = function(request, ...rest) {
+    if (request === "path" || request === "node:path") {
+        return nodePath.win32;
+    }
+    return originalLoad.call(this, request, ...rest);
+};
+process.cwd = () => CWD;
+
+const { Linter, ESLint } = require("../lib/api");
+
+const config = { rules: { "no-undef": "error" } };
+const files = {
+    "inside cwd       ": "C:\\Project\\foo.js",
+    "same drive, outside": "C:\\Other\\foo.js",
+    "different drive  ": "F:\\foo.js"
+};
+
+console.log(`path.win32.relative(${JSON.stringify(CWD)}, "C:\\\\Other\\\\foo.js") = ${JSON.stringify(nodePath.win32.relative(CWD, "C:\\Other\\foo.js"))}`);
+console.log(`path.win32.relative(${JSON.stringify(CWD)}, "F:\\\\foo.js")        = ${JSON.stringify(nodePath.win32.relative(CWD, "F:\\foo.js"))}`);
+
+(async () => {
+    console.log("\n== Linter#verify (flat) ==");
+    const linter = new Linter({ configType: "flat", cwd: CWD });
+
+    for (const [label, file] of Object.entries(files)) {
+        const msgs = linter.verify("foo();", config, file);
+        console.log(`${label} ${file.padEnd(20)} -> ${msgs.map(m => m.ruleId ? `${m.ruleId}: ${m.message}` : m.message).join(" | ") || "(no messages)"}`);
+    }
+
+    console.log("\n== ESLint#isPathIgnored / ESLint#lintText ==");
+    const eslint = new ESLint({ cwd: CWD, overrideConfigFile: true, overrideConfig: config });
+
+    for (const [label, file] of Object.entries(files)) {
+        const ignored = await eslint.isPathIgnored(file);
+        const [result] = await eslint.lintText("foo();", { filePath: file, warnIgnored: true });
+        const msgs = result.messages.map(m => m.ruleId ? `${m.ruleId}: ${m.message}` : m.message).join(" | ");
+
+        console.log(`${label} ${file.padEnd(20)} -> isPathIgnored=${ignored}; lintText: ${msgs}`);
+    }
+
+    const crossDriveIgnored = await eslint.isPathIgnored(files["different drive  "]);
+
+    console.log(crossDriveIgnored
+        ? "\nOK: file on a different drive is ignored."
+        : "\nBUG REPRODUCED: F:\\foo.js (different drive than cwd C:\\Project) is NOT ignored and gets linted.");
+    process.exitCode = crossDriveIgnored ? 0 : 1;
+})();
